import React, { useState, useEffect } from 'react';

function MERNApp() {
  const [users, setUsers] = useState([]);
  const [formData, setFormData] = useState({ name: '', email: '', role: '' });
  const [editingUser, setEditingUser] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const API_URL = 'http://localhost:5000/api/users';

  const fetchUsers = async () => {
    try {
      const response = await fetch(API_URL);
      if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
      const data = await response.json();
      setUsers(data);
      setError('');
    } catch (err) {
      setError('Unable to connect to server. Make sure backend is running on port 5000.');
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async () => {
    if (!formData.name || !formData.email || !formData.role) {
      alert('Please fill all fields');
      return;
    }

    try {
      setLoading(true);
      setError('');
      setSuccess('');
      
      if (editingUser) {
        const response = await fetch(`${API_URL}/${editingUser._id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(formData)
        });
        if (!response.ok) throw new Error('Failed to update user');
        setSuccess('User updated successfully!');
        setEditingUser(null);
      } else {
        const response = await fetch(API_URL, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(formData)
        });
        if (!response.ok) throw new Error('Failed to add user');
        setSuccess('User added successfully!');
      }
      
      setFormData({ name: '', email: '', role: '' });
      setTimeout(() => fetchUsers(), 500);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
      setTimeout(() => setSuccess(''), 3000);
    }
  };

  const handleEdit = (user) => {
    setEditingUser(user);
    setFormData({ name: user.name, email: user.email, role: user.role });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this user?')) return;
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/${id}`, { method: 'DELETE' });
      if (!response.ok) throw new Error('Failed to delete user');
      setSuccess('User deleted successfully!');
      setUsers(users.filter(u => u._id !== id));
    } catch (err) {
      setError(err.message);
      fetchUsers();
    } finally {
      setLoading(false);
      setTimeout(() => setSuccess(''), 3000);
    }
  };

  const handleCancel = () => {
    setEditingUser(null);
    setFormData({ name: '', email: '', role: '' });
  };

  const styles = {
    container: {
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      padding: '40px 20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif'
    },
    wrapper: {
      maxWidth: '1100px',
      margin: '0 auto'
    },
    header: {
      textAlign: 'center',
      marginBottom: '50px'
    },
    title: {
      fontSize: '48px',
      fontWeight: 'bold',
      color: 'white',
      marginBottom: '10px',
      textShadow: '0 4px 6px rgba(0,0,0,0.3)'
    },
    subtitle: {
      fontSize: '18px',
      color: 'rgba(255,255,255,0.9)'
    },
    alert: {
      padding: '16px 24px',
      borderRadius: '12px',
      marginBottom: '24px',
      display: 'flex',
      alignItems: 'center',
      fontWeight: '500',
      boxShadow: '0 10px 25px rgba(0,0,0,0.2)'
    },
    errorAlert: {
      background: 'rgba(239, 68, 68, 0.95)',
      color: 'white',
      borderLeft: '4px solid #dc2626'
    },
    successAlert: {
      background: 'rgba(34, 197, 94, 0.95)',
      color: 'white',
      borderLeft: '4px solid #16a34a'
    },
    card: {
      background: 'rgba(255, 255, 255, 0.95)',
      borderRadius: '20px',
      padding: '40px',
      marginBottom: '30px',
      boxShadow: '0 20px 60px rgba(0,0,0,0.3)',
      backdropFilter: 'blur(10px)'
    },
    cardHeader: {
      display: 'flex',
      alignItems: 'center',
      gap: '15px',
      marginBottom: '30px'
    },
    iconBox: {
      width: '50px',
      height: '50px',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      borderRadius: '12px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontSize: '24px'
    },
    cardTitle: {
      fontSize: '28px',
      fontWeight: 'bold',
      color: '#1f2937',
      margin: 0
    },
    formGroup: {
      marginBottom: '24px'
    },
    label: {
      display: 'block',
      fontSize: '14px',
      fontWeight: '600',
      color: '#374151',
      marginBottom: '8px'
    },
    input: {
      width: '100%',
      padding: '14px 16px',
      fontSize: '16px',
      border: '2px solid #e5e7eb',
      borderRadius: '12px',
      outline: 'none',
      transition: 'all 0.3s',
      boxSizing: 'border-box'
    },
    inputFocus: {
      border: '2px solid #667eea'
    },
    buttonGroup: {
      display: 'flex',
      gap: '12px',
      marginTop: '10px'
    },
    button: {
      flex: 1,
      padding: '14px 24px',
      fontSize: '16px',
      fontWeight: '600',
      border: 'none',
      borderRadius: '12px',
      cursor: 'pointer',
      transition: 'all 0.3s',
      boxShadow: '0 4px 12px rgba(0,0,0,0.15)'
    },
    primaryButton: {
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: 'white'
    },
    secondaryButton: {
      background: '#6b7280',
      color: 'white'
    },
    disabledButton: {
      background: '#d1d5db',
      cursor: 'not-allowed'
    },
    statsBar: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      marginBottom: '24px'
    },
    badge: {
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: 'white',
      padding: '8px 20px',
      borderRadius: '20px',
      fontSize: '14px',
      fontWeight: 'bold'
    },
    userCard: {
      background: '#f9fafb',
      border: '2px solid #e5e7eb',
      borderRadius: '16px',
      padding: '24px',
      marginBottom: '16px',
      transition: 'all 0.3s'
    },
    userCardHover: {
      borderColor: '#667eea',
      boxShadow: '0 8px 20px rgba(102, 126, 234, 0.2)',
      transform: 'translateY(-2px)'
    },
    userInfo: {
      display: 'flex',
      alignItems: 'center',
      gap: '20px',
      marginBottom: '16px'
    },
    avatar: {
      width: '60px',
      height: '60px',
      borderRadius: '50%',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      color: 'white',
      fontSize: '24px',
      fontWeight: 'bold',
      flexShrink: 0
    },
    userDetails: {
      flex: 1
    },
    userName: {
      fontSize: '20px',
      fontWeight: 'bold',
      color: '#1f2937',
      marginBottom: '4px'
    },
    userEmail: {
      fontSize: '14px',
      color: '#6b7280'
    },
    roleBadge: {
      display: 'inline-block',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: 'white',
      padding: '6px 16px',
      borderRadius: '12px',
      fontSize: '13px',
      fontWeight: '600'
    },
    actionButtons: {
      display: 'flex',
      gap: '10px',
      marginTop: '16px'
    },
    editButton: {
      padding: '10px 20px',
      background: '#10b981',
      color: 'white',
      border: 'none',
      borderRadius: '10px',
      fontSize: '14px',
      fontWeight: '600',
      cursor: 'pointer',
      transition: 'all 0.3s'
    },
    deleteButton: {
      padding: '10px 20px',
      background: '#ef4444',
      color: 'white',
      border: 'none',
      borderRadius: '10px',
      fontSize: '14px',
      fontWeight: '600',
      cursor: 'pointer',
      transition: 'all 0.3s'
    },
    emptyState: {
      textAlign: 'center',
      padding: '60px 20px'
    },
    footer: {
      textAlign: 'center',
      marginTop: '40px',
      color: 'rgba(255,255,255,0.8)',
      fontSize: '14px'
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.wrapper}>
        <div style={styles.header}>
          <h1 style={styles.title}>MERN User Manager</h1>
          <p style={styles.subtitle}>Manage your team with style</p>
        </div>

        {error && (
          <div style={{...styles.alert, ...styles.errorAlert}}>
            <span style={{fontSize: '24px', marginRight: '12px'}}>⚠️</span>
            <span>{error}</span>
          </div>
        )}

        {success && (
          <div style={{...styles.alert, ...styles.successAlert}}>
            <span style={{fontSize: '24px', marginRight: '12px'}}>✓</span>
            <span>{success}</span>
          </div>
        )}

        <div style={styles.card}>
          <div style={styles.cardHeader}>
            <div style={styles.iconBox}>
              <span>{editingUser ? '✏️' : '➕'}</span>
            </div>
            <h2 style={styles.cardTitle}>{editingUser ? 'Edit User' : 'Add New User'}</h2>
          </div>
          
          <div style={styles.formGroup}>
            <label style={styles.label}>Full Name</label>
            <input
              type="text"
              name="name"
              placeholder="John Doe"
              value={formData.name}
              onChange={handleChange}
              style={styles.input}
              disabled={loading}
            />
          </div>
          
          <div style={styles.formGroup}>
            <label style={styles.label}>Email Address</label>
            <input
              type="email"
              name="email"
              placeholder="john@example.com"
              value={formData.email}
              onChange={handleChange}
              style={styles.input}
              disabled={loading}
            />
          </div>
          
          <div style={styles.formGroup}>
            <label style={styles.label}>Role</label>
            <input
              type="text"
              name="role"
              placeholder="Administrator, Developer, etc."
              value={formData.role}
              onChange={handleChange}
              style={styles.input}
              disabled={loading}
            />
          </div>

          <div style={styles.buttonGroup}>
            <button
              onClick={handleSubmit}
              disabled={loading}
              style={{
                ...styles.button, 
                ...styles.primaryButton,
                ...(loading ? styles.disabledButton : {})
              }}
              onMouseEnter={(e) => !loading && (e.target.style.transform = 'translateY(-2px)')}
              onMouseLeave={(e) => (e.target.style.transform = 'translateY(0)')}
            >
              {loading ? '⏳ Processing...' : editingUser ? '💾 Update User' : '➕ Add User'}
            </button>
            
            {editingUser && (
              <button
                onClick={handleCancel}
                disabled={loading}
                style={{...styles.button, ...styles.secondaryButton}}
                onMouseEnter={(e) => !loading && (e.target.style.opacity = '0.8')}
                onMouseLeave={(e) => (e.target.style.opacity = '1')}
              >
                ✕ Cancel
              </button>
            )}
          </div>
        </div>

        <div style={styles.card}>
          <div style={styles.statsBar}>
            <div style={styles.cardHeader}>
              <div style={styles.iconBox}>
                <span>👥</span>
              </div>
              <h2 style={styles.cardTitle}>Team Members</h2>
            </div>
            <div style={styles.badge}>
              {users.length} {users.length === 1 ? 'Member' : 'Members'}
            </div>
          </div>
          
          {users.length === 0 ? (
            <div style={styles.emptyState}>
              <div style={{fontSize: '64px', marginBottom: '16px'}}>📭</div>
              <p style={{fontSize: '20px', color: '#6b7280', marginBottom: '8px'}}>No team members yet</p>
              <p style={{fontSize: '14px', color: '#9ca3af'}}>Add your first member to get started</p>
            </div>
          ) : (
            <div>
              {users.map((user) => (
                <div 
                  key={user._id} 
                  style={styles.userCard}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.borderColor = '#667eea';
                    e.currentTarget.style.boxShadow = '0 8px 20px rgba(102, 126, 234, 0.2)';
                    e.currentTarget.style.transform = 'translateY(-2px)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.borderColor = '#e5e7eb';
                    e.currentTarget.style.boxShadow = 'none';
                    e.currentTarget.style.transform = 'translateY(0)';
                  }}
                >
                  <div style={styles.userInfo}>
                    <div style={styles.avatar}>
                      {user.name.charAt(0).toUpperCase()}
                    </div>
                    <div style={styles.userDetails}>
                      <h3 style={styles.userName}>{user.name}</h3>
                      <p style={styles.userEmail}>{user.email}</p>
                    </div>
                  </div>
                  <div style={{marginBottom: '12px'}}>
                    <span style={styles.roleBadge}>{user.role}</span>
                  </div>
                  <div style={styles.actionButtons}>
                    <button
                      onClick={() => handleEdit(user)}
                      disabled={loading}
                      style={styles.editButton}
                      onMouseEnter={(e) => !loading && (e.target.style.opacity = '0.85')}
                      onMouseLeave={(e) => (e.target.style.opacity = '1')}
                    >
                      ✏️ Edit
                    </button>
                    <button
                      onClick={() => handleDelete(user._id)}
                      disabled={loading}
                      style={styles.deleteButton}
                      onMouseEnter={(e) => !loading && (e.target.style.opacity = '0.85')}
                      onMouseLeave={(e) => (e.target.style.opacity = '1')}
                    >
                      🗑️ Delete
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        <div style={styles.footer}>
          <p>Built with MongoDB • Express • React • Node.js</p>
        </div>
      </div>
    </div>
  );
}

export default MERNApp;
